  return value
}
interface ClockReader { read() -> i64 }
class RejectedClock implements ClockReader {
  read() -> i64 { return rejectedFallible() }
}
fn invoke(body: fn() -> i64, reader: ClockReader, mode: i64) -> i64 {
  var live = sys.Pipe(2147483646, 2147483647)
  defer {
    live.closeRead()
    live.closeWrite()
  }
  var result = 0
